 const d=openDialog('access-dialog',`${dialogHead('access-title','readingSettings')}<section class="settings-section"><h3>${t('appearance')}</h3><div class="size-control"><span>${t('textSize')}</span><button id="smaller" aria-label="${t('smaller')}">A−</button><output id="text-size">${textLevel}%</output><button id="larger" aria-label="${t('larger')}">A+</button></div>${[['contrast',contrast],['motion',motion],['lineSpacing',spacing]].map(([k,on])=>`<label class="setting-switch"><span>${t(k)}</span><input id="setting-${k}" role="switch" type="checkbox" ${on?'checked':''}></label>`).join('')}</section><section class="settings-section"><h3>${t('voice')}</h3>${copy(audioLanguages.includes(lang)?'voiceHelp':'textOnly','p','help')}<fieldset class="speed-control"><legend>${t('speed')}</legend>${[[.75,'slower'],[.9,'normalSpeed'],[1.05,'faster']].map(([rate,k])=>`<label><input name="speed" type="radio" value="${rate}" ${speechRate===rate?'checked':''}><span>${t(k)}</span></label>`).join('')}</fieldset><p id="voice-status" role="status" class="help"></p>${details('audioCache',copy('audioData')+button('clear-audio','clearAudio','text-button'))}${copy('audioDraft','p','micro')}</section>${copy('readingPreferences','p','help')}${button('reset-settings','resetSettings','text-button')}`);
 function size(amount){textLevel=Math.max(90,Math.min(200,textLevel+amount));document.documentElement.style.fontSize=textLevel+'%';$('#text-size').textContent=textLevel+'%';$('#smaller').disabled=textLevel<=90;$('#larger').disabled=textLevel>=200;rememberReading();}
 $('#smaller').onclick=()=>size(-10);$('#larger').onclick=()=>size(10);size(0);
 for(const [key,cls] of [['contrast','high-contrast'],['motion','no-motion'],['lineSpacing','more-spacing']])$('#setting-'+key).onchange=e=>{document.body.classList.toggle(cls,e.target.checked);rememberReading();};
 d.querySelectorAll('[name=speed]').forEach(el=>el.onchange=()=>{speechRate=Number(el.value);rememberReading();reader.stop();});

 $('#clear-audio').onclick=async()=>{reader.stop();try{for(const key of await caches.keys())if(key.startsWith('virasat-audio-'))await caches.delete(key);$('#voice-status').textContent=t('audioCleared');}catch{$('#voice-status').textContent=t('speechError');}};
 $('#reset-settings').onclick=()=>{textLevel=100;size(0);speechRate=.9;document.body.classList.remove('high-contrast','no-motion','more-spacing');try{localStorage.removeItem(preferencesKey);}catch{}d.close();accessDialog();};
