export function emptyAccount(){return {id:crypto.randomUUID(),type:'demat',institution:'',institutionId:'',linkedDematId:'',label:'',owner:'',nomineeNote:'',nominees:[],last4:'',holding:'unknown',product:'unknown',mfMode:'unknown',nomination:'unknown',review:'reported',checkedOn:'',submittedOn:'',confirmationOn:'',followupOn:'',familyReviewedOn:'',recordKind:'',recordNote:'',recordLocation:'',evidenceScope:'status',confirmationChecked:false,events:[]};}
